<template>
  <section aria-label="原住院GCS分项来源">
    <p v-if="!allowed">请以有权限的工作人员身份明确选择原患者和住院。</p>
    <template v-else>
      <p v-if="governance">全院原GCS来源审计，保留原患者、原住院、实际E/V/M与两个真实时刻。NT不记1、不补总分；查看和撤销不调用模型。</p><p v-else>患者 #{{ patientId }} · 原住院 {{ admissionId }}。保留实际E/V/M和两个真实时刻；NT不记1、不补总分。登记与撤销不调用模型。</p>
      <el-collapse><el-collapse-item v-if="!governance && canRecord" title="登记原始GCS分项">
        <el-form label-position="top" :disabled="saving" @submit.prevent>
          <el-form-item label="GCS实际观察UTC"><el-input v-model="form.observed_at" aria-label="GCS实际观察UTC" placeholder="明确填写实际带时区ISO，不自动使用当前时刻" /></el-form-item>
          <fieldset v-for="(label, key) in labels" :key="key"><legend>{{ label }}</legend><el-select v-model="form.components[key].choice" :aria-label="`GCS${label}原分项`" clearable placeholder="明确选择原分项或缺测原因"><el-option v-for="score in maxima[key]" :key="score" :value="score" :label="String(score)" /><el-option v-for="(text, code) in absent" :key="code" :value="code" :label="text" /></el-select></fieldset>
          <el-button :loading="anchorLoading" @click="loadAnchors">读取可明确关联的原点测</el-button>
          <el-form-item label="同次检查的原点测关联（可选）"><el-select v-model="form.anchorId" aria-label="GCS明确关联原点测" clearable placeholder="不自动关联最近点测"><el-option v-for="row in anchors" :key="row.observation_id" :value="row.observation_id" :label="`${row.observed_at} · ${row.observation_id}`" /></el-select></el-form-item>
          <template v-if="form.anchorId"><el-checkbox v-model="form.same_exam_confirmed">我已核实GCS与所选原点测属于同次检查，实际时间分别保留</el-checkbox><el-input v-model="form.same_exam_basis_note" aria-label="GCS同次检查关联依据" type="textarea" maxlength="1000" placeholder="至少20字，记录原同次检查的实际依据；不能只取最近记录" /></template>
          <el-input v-model="form.note" aria-label="GCS原来源备注" type="textarea" maxlength="1000" />
          <p>原记录须先登记，再建立新的as_of观测窗。晚于旧截止的登记不会补入旧窗；不指示停镇静、唤醒或代填未测分项。</p><p v-if="draftError" role="alert">{{ draftError }}</p><el-button type="primary" :disabled="!canSave" :loading="saving" @click="save">仅登记GCS原来源</el-button>
        </el-form>
      </el-collapse-item></el-collapse>
      <el-button :loading="loading" @click="load">刷新GCS原来源目录</el-button><p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
      <el-table :data="items" aria-label="GCS原来源目录"><el-table-column v-if="governance" label="原患者与住院" min-width="250"><template #default="{row}">#{{ row.patient_id }} · {{ row.admission_id }}</template></el-table-column><el-table-column prop="gcs_observation_id" label="原来源ID" min-width="250" /><el-table-column label="实际观察与登记UTC" min-width="230"><template #default="{ row }">{{ row.observed_at }}<br />{{ row.recorded_at }}</template></el-table-column><el-table-column label="原分项与完整总分"><template #default="{ row }"><span v-for="(label,key) in labels" :key="key">{{ label }} {{ componentText(row.payload.components[key]) }} </span><br />完整总分 {{ row.derived_total ?? '未取得，不补0' }}</template></el-table-column><el-table-column label="治理"><template #default="{ row }">{{ row.status }} · v{{ row.revision }}<br />原点关联 {{ row.anchor_current === true ? '本次有效' : '未确认或已失效' }}<el-button @click="inspect(row)">核对GCS原来源</el-button></template></el-table-column></el-table>
      <p>目录共 {{ total ?? '未知' }} 项。</p><el-pagination v-if="total > 50" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next" @current-change="load" />
    </template>
    <el-dialog v-model="detailOpen" title="GCS原来源冻结审计" width="min(850px,95vw)"><template v-if="allowed && detail"><p>患者 #{{ detail.patient_id }} · 原住院 {{ detail.admission_id }} · {{ detail.source_id }}</p><p>实际观察 {{ detail.observed_at }}；系统登记 {{ detail.recorded_at }}；原摘要 {{ detail.content_hash }}。</p><p v-for="(label,key) in labels" :key="key">{{ label }}：{{ componentText(detail.payload.components[key]) }}</p><p>完整总分 {{ detail.derived_total ?? '未取得，不估算' }}；状态 {{ detail.status }} · v{{ detail.revision }}。</p><p>明确原点关联 {{ detail.payload.anchor_point?.observation_id ?? '未关联' }}；同次依据 {{ detail.payload.same_exam_basis_note ?? '未声明' }}；原备注 {{ detail.payload.note }}。</p><p v-for="reason in detail.anchor_exclusion_reasons || []" :key="reason">{{ reason }}</p><p>历史审计保留当时的关联及NT记录。</p><template v-if="detail.can_revoke === true && detail.status === 'active'"><el-input v-model="reason" aria-label="GCS来源撤销依据" maxlength="1000" /><el-button type="danger" :loading="revoking" :disabled="reason.trim().length < 5" @click="revoke">撤销GCS原来源</el-button></template></template><p v-if="detailError" role="alert">{{ detailError }}</p></el-dialog>
  </section>
</template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { getInpatientPoints, observationTime } from "@/api/inpatientObservations";
import { createGcsObservation, getAdminGcsObservation, getAdminGcsObservations, getGcsObservation, getGcsObservations, gcsAbsentLabels as absent, gcsComponentLabels as labels, gcsCanonical, gcsObservationMatches, revokeGcsObservation } from "@/api/inpatientGcs";
const props = defineProps({ patientId: { type: Number, default: null }, admissionId: { type: String, default: "" }, active: { type: Boolean, default: true }, governance: { type: Boolean, default: false } }), emit = defineEmits(["source-created", "source-revoked"]), store = useStore();
const roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => props.active && !!store.state.user.accessToken && (props.governance ? roles.value.includes("super_admin") : Number.isSafeInteger(props.patientId) && props.patientId > 0 && !!props.admissionId && roles.value.some(role => ["nurse", "doctor", "director", "admin", "super_admin"].includes(role))));
const maxima = { eye: 4, verbal: 5, motor: 6 }, blank = () => ({ observed_at: "", components: { eye: { choice: "" }, verbal: { choice: "" }, motor: { choice: "" } }, anchorId: "", same_exam_confirmed: false, same_exam_basis_note: "", note: "" });
const canRecord = ref(false);
const form = ref(blank()), items = ref([]), anchors = ref([]), page = ref(1), total = ref(null), loading = ref(false), anchorLoading = ref(false), saving = ref(false), revoking = ref(false), error = ref(""), notice = ref(""), draftError = ref(""), detail = ref(null), detailOpen = ref(false), detailError = ref(""), reason = ref("");
let epoch = 0, listSeq = 0, detailSeq = 0, anchorSeq = 0, inactive = false;
const scope = () => JSON.stringify([props.patientId, props.admissionId, props.active, props.governance, store.state.user.accessToken, roles.value]), capture = () => ({ epoch, key: scope(), patientId: props.patientId, admissionId: props.admissionId }), current = ticket => ticket.epoch === epoch && ticket.key === scope() && allowed.value && !inactive;
const query = ticket => ({ ...(ticket.patientId ? { patient_id: ticket.patientId } : {}), ...(ticket.admissionId ? { admission_id: ticket.admissionId } : {}) });
const componentText = item => item.score ?? absent[item.absent_reason] ?? "未知";
function payload() {
  if (props.governance) throw new Error("治理入口不能登记临床原记录");
  const observed = observationTime(form.value.observed_at).text, components = {};
  for (const key of Object.keys(maxima)) { const choice = form.value.components[key].choice; if (Number.isInteger(choice) && choice >= 1 && choice <= maxima[key]) components[key] = { score: choice, absent_reason: null }; else if (choice in absent) components[key] = { score: null, absent_reason: choice }; else throw new Error("每个原分项须明确填写合法分数或NT/未记录，不补默认15"); }
  const point = form.value.anchorId ? anchors.value.find(row => row.observation_id === form.value.anchorId) : null;
  if (form.value.anchorId && (!point || !form.value.same_exam_confirmed || form.value.same_exam_basis_note.trim().length < 20)) throw new Error("明确关联须有原点、同次检查确认和至少20字原依据");
  return { ...query(capture()), observed_at: observed, payload: { components, anchor_point: point ? { observation_id: point.observation_id, expected_content_hash: point.content_hash } : null, same_exam_confirmed: !!point && form.value.same_exam_confirmed, same_exam_basis_note: point ? form.value.same_exam_basis_note.trim() : null, note: form.value.note } };
}
const canSave = computed(() => { try { payload(); return allowed.value && canRecord.value && !saving.value; } catch { return false; } });
function clearDetail() { detailSeq++; detail.value = null; detailOpen.value = false; detailError.value = reason.value = ""; revoking.value = false; }
function reset() { epoch++; listSeq++; anchorSeq++; clearDetail(); form.value = blank(); canRecord.value = false; items.value = []; anchors.value = []; page.value = 1; total.value = null; loading.value = anchorLoading.value = saving.value = false; error.value = notice.value = draftError.value = ""; }
async function load() { if (!allowed.value || inactive) return; const ticket = capture(), seq = ++listSeq; items.value = []; loading.value = true; error.value = ""; try { const res = await (props.governance ? getAdminGcsObservations : getGcsObservations)({ ...query(ticket), page: page.value, page_size: 50 }); if (!current(ticket) || seq !== listSeq) return; const data = res.data; if (!Array.isArray(data?.items) || data.items.some(row => (ticket.patientId && row.patient_id !== ticket.patientId) || (ticket.admissionId && row.admission_id !== ticket.admissionId) || !gcsObservationMatches(row, row.patient_id, row.admission_id))) throw new Error("GCS目录与原患者、住院或原分项不一致"); items.value = data.items; total.value = data.total; canRecord.value = data.can_record === true; } catch (failure) { if (current(ticket) && seq === listSeq) error.value = failure?.message || "GCS目录未能核对"; } finally { if (current(ticket) && seq === listSeq) loading.value = false; } }
async function loadAnchors() { if (!allowed.value || inactive || props.governance) return; const ticket = capture(), seq = ++anchorSeq; anchorLoading.value = true; anchors.value = []; form.value.anchorId = ""; error.value = ""; try { const res = await getInpatientPoints({ ...query(ticket), status: "active" }); if (!current(ticket) || seq !== anchorSeq) return; const rows = Array.isArray(res.data) ? res.data : res.data?.items; if (!Array.isArray(rows) || rows.some(row => row.patient_id !== ticket.patientId || row.admission_id !== ticket.admissionId || row.status !== "active" || !/^[a-f0-9]{64}$/.test(row.content_hash || ""))) throw new Error("同次检查原点目录与原住院不一致"); anchors.value = rows; } catch (failure) { if (current(ticket) && seq === anchorSeq) error.value = failure?.message || "原点目录未能核对"; } finally { if (current(ticket) && seq === anchorSeq) anchorLoading.value = false; } }
async function save() { if (!canSave.value || inactive) return; const ticket = capture(); let body; try { body = payload(); } catch (failure) { draftError.value = failure.message; return; } saving.value = true; error.value = ""; try { const res = await createGcsObservation(body); if (!current(ticket)) return; if (!gcsObservationMatches(res.data, ticket.patientId, ticket.admissionId) || res.data.status !== "active" || res.data.revision !== 1 || gcsCanonical(res.data.payload) !== gcsCanonical(body.payload) || observationTime(res.data.observed_at).microseconds !== observationTime(body.observed_at).microseconds) throw new Error("GCS登记回执与原住院、原时刻或原分项不一致"); form.value = blank(); emit("source-created", res.data); notice.value = "GCS原来源已登记；请建立新截止窗并明确选择，尚未调用模型或评估。"; await load(); } catch (failure) { if (current(ticket)) error.value = failure?.message || "GCS登记失败"; } finally { if (current(ticket)) saving.value = false; } }
async function inspect(row) { clearDetail(); if (!allowed.value || inactive) return; const ticket = capture(), seq = detailSeq; detailOpen.value = true; try { const res = await (props.governance ? getAdminGcsObservation(row.gcs_observation_id) : getGcsObservation(row.gcs_observation_id, query(ticket))); if (!current(ticket) || seq !== detailSeq || !detailOpen.value) return; if (!gcsObservationMatches(res.data, row.patient_id, row.admission_id) || res.data.gcs_observation_id !== row.gcs_observation_id || res.data.content_hash !== row.content_hash) throw new Error("GCS详情与明确原记录不一致"); detail.value = res.data; } catch (failure) { if (current(ticket) && seq === detailSeq) detailError.value = failure?.message || "GCS原来源未能核对"; } }
async function revoke() { if (!allowed.value || inactive || detail.value?.can_revoke !== true || revoking.value || reason.value.trim().length < 5) return; const original = detail.value, ticket = capture(), reasonText = reason.value.trim(); clearDetail(); revoking.value = true; try { const res = await revokeGcsObservation(original.gcs_observation_id, { patient_id: original.patient_id, admission_id: original.admission_id, expected_revision: original.revision, reason: reasonText }); if (!current(ticket)) return; if (!gcsObservationMatches(res.data, original.patient_id, original.admission_id) || res.data.gcs_observation_id !== original.gcs_observation_id || res.data.content_hash !== original.content_hash || res.data.status !== "revoked" || res.data.revision !== original.revision + 1) throw new Error("GCS撤销回执与原版本不一致"); emit("source-revoked", res.data); notice.value = "GCS原来源已撤销；请重建窗口并核对来源，旧来源不能继续计算。"; await load(); } catch (failure) { if (current(ticket)) error.value = failure?.message || "GCS撤销失败"; } finally { if (current(ticket)) revoking.value = false; } }
watch(() => form.value.anchorId, () => { form.value.same_exam_confirmed = false; form.value.same_exam_basis_note = ""; });
watch(scope, () => { reset(); load(); }, { immediate: true, flush: "sync" });
onDeactivated(() => { inactive = true; reset(); }); onActivated(() => { if (inactive) { inactive = false; reset(); load(); } }); onBeforeUnmount(() => { inactive = true; reset(); });
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere;}fieldset{display:inline-block;min-width:180px;margin:8px;}.el-select{width:100%;}.el-button{margin:8px 8px 8px 0;}.el-checkbox{height:auto;white-space:normal;}</style>
